package com.harvestflow.api.service;
import com.harvestflow.api.domain.entity.*; import com.harvestflow.api.domain.enums.*; import com.harvestflow.api.dto.delivery.*; import com.harvestflow.api.exception.*; import com.harvestflow.api.repository.*; import com.harvestflow.api.service.notification.NotificationService; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.security.SecureRandom; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class DeliveryService {
 private final DeliveryAssignmentRepository assignments; private final DeliveryOtpRepository otps; private final MarketOrderRepository orders; private final HarvestCaseRepository cases; private final PaymentService payments; private final PaymentRecordRepository paymentRecords; private final NotificationService notifications; private final PasswordEncoder encoder; private final SecureRandom random=new SecureRandom();
 @Transactional public DeliveryAssignmentResponse assign(UUID orderId,String deliveryBoyUsername,User actor){if(actor.getRole()!=UserRole.PICKUP_PERSON && actor.getRole()!=UserRole.ADMIN)throw new ForbiddenRoleException("Only delivery operations staff can assign delivery.");MarketOrder o=orders.findById(orderId).orElseThrow(()->new ResourceNotFoundException("Order not found: "+orderId));DeliveryAssignment d=assignments.findByMarketOrderId(orderId).orElseGet(DeliveryAssignment::new);d.setMarketOrder(o);d.setDeliveryBoyUsername(deliveryBoyUsername);d.setStatus(DeliveryStatus.ASSIGNED);return DeliveryAssignmentResponse.from(assignments.save(d));}
 public List<DeliveryAssignmentResponse> assignedTo(User actor){if(actor.getRole()!=UserRole.PICKUP_PERSON && actor.getRole()!=UserRole.ADMIN)throw new ForbiddenRoleException("Delivery access denied.");return assignments.findByDeliveryBoyUsernameOrderByAssignedAtDesc(actor.getUsername()).stream().map(DeliveryAssignmentResponse::from).toList();}
 @Transactional public DeliveryAssignmentResponse confirmPickup(UUID orderId,User actor){DeliveryAssignment d=forBoy(orderId,actor);d.setPickupConfirmed(true);d.setStatus(DeliveryStatus.PICKED_UP);d.setPickedUpAt(Instant.now());return DeliveryAssignmentResponse.from(assignments.save(d));}
 @Transactional public DeliveryAssignmentResponse reachBuyer(UUID orderId,User actor){DeliveryAssignment d=forBoy(orderId,actor);if(!d.isPickupConfirmed())throw new InvalidTransitionException("Pickup must be confirmed first.");d.setBuyerReached(true);d.setStatus(DeliveryStatus.AT_BUYER);d.setBuyerReachedAt(Instant.now());return DeliveryAssignmentResponse.from(assignments.save(d));}
 @Transactional public String generateOtp(UUID orderId,User buyer){MarketOrder o=orders.findById(orderId).orElseThrow(()->new ResourceNotFoundException("Order not found: "+orderId));if(!o.getBuyer().getId().equals(buyer.getId()))throw new ForbiddenRoleException("Only the buyer can generate delivery OTP.");DeliveryOtp x=otps.findByMarketOrderId(orderId).orElseGet(DeliveryOtp::new);String otp=String.format("%06d",random.nextInt(1_000_000));x.setMarketOrder(o);x.setOtpHash(encoder.encode(otp));x.setExpiresAt(Instant.now().plusSeconds(600));x.setConsumedAt(null);otps.save(x);notifications.notify(buyer.getUsername(),NotificationCategory.PAYMENT,"Delivery OTP generated","Use the delivery OTP at handover. It expires in 10 minutes.","MARKET_ORDER",orderId);return otp;}
 @Transactional public DeliveryAssignmentResponse complete(UUID orderId,String otp,User actor){DeliveryAssignment d=forBoy(orderId,actor);if(!d.isBuyerReached())throw new InvalidTransitionException("Delivery can be completed only after reaching the buyer.");MarketOrder o=d.getMarketOrder();if(o.getPaymentStatus()!=PaymentStatus.SUCCEEDED)throw new InvalidTransitionException("Payment must be PAID before delivery completion.");DeliveryOtp x=otps.findByMarketOrderId(orderId).orElseThrow(()->new InvalidTransitionException("Delivery OTP has not been generated."));if(x.getConsumedAt()!=null||Instant.now().isAfter(x.getExpiresAt())||!encoder.matches(otp,x.getOtpHash()))throw new InvalidTransitionException("Invalid or expired delivery OTP.");if(cases.findByMarketOrderId(orderId).map(c->c.getStatus()!=CaseStatus.SALES_COMPLETED).orElse(true))throw new InvalidMarketplaceStateException("Existing HarvestFlow internal workflow must reach SALES_COMPLETED before final delivery completion.");x.setConsumedAt(Instant.now());otps.save(x);d.setStatus(DeliveryStatus.COMPLETED);d.setCompletedAt(Instant.now());o.setStatus(OrderStatus.COMPLETED);o.setDeliveredAt(Instant.now());orders.save(o);notifications.notify(o.getBuyer().getUsername(),NotificationCategory.PAYMENT,"Delivery completed","Your order has been delivered and payment is confirmed.","MARKET_ORDER",orderId);notifications.notify(o.getSeller().getUsername(),NotificationCategory.PAYMENT,"Delivery completed","Your order has been delivered and payment is confirmed.","MARKET_ORDER",orderId);return DeliveryAssignmentResponse.from(assignments.save(d));}
 public ReceiptResponse receipt(UUID orderId,User actor){MarketOrder o=orders.findById(orderId).orElseThrow(()->new ResourceNotFoundException("Order not found: "+orderId));if(!o.getBuyer().getId().equals(actor.getId())&&!o.getSeller().getId().equals(actor.getId()))throw new ForbiddenRoleException("Receipt access denied.");if(o.getStatus()!=OrderStatus.COMPLETED)throw new InvalidTransitionException("Receipt is available after delivery completion.");String ref=paymentRecords.findByReferenceTypeAndReferenceIdOrderByCreatedAtDesc(PaymentReferenceType.MARKET_ORDER,orderId).stream().filter(p->p.getStatus()==PaymentStatus.SUCCEEDED||p.getStatus()==PaymentStatus.SUCCEEDED).findFirst().map(PaymentRecord::getGatewayReference).orElse(null);return ReceiptResponse.from(o,ref);}
 private DeliveryAssignment forBoy(UUID id,User actor){DeliveryAssignment d=assignments.findByMarketOrderId(id).orElseThrow(()->new ResourceNotFoundException("Delivery assignment not found."));if(actor.getRole()!=UserRole.ADMIN&&!actor.getUsername().equals(d.getDeliveryBoyUsername()))throw new ForbiddenRoleException("This delivery is assigned to another delivery person.");return d;}
}
